(()=>{const form=document.querySelector('#contact-form');if(!form)return;const button=form.querySelector('button[type="submit"]'),status=document.querySelector('#form-status');const next=form.querySelector('[name="_next"]');if(next)next.value=new URL('/danke.html',window.location.origin).href;const fields=[...form.querySelectorAll('[required]')];form.noValidate=true;function validate(field){let message='';if(!field.value.trim())message=field.name==='name'?'Bitte gib deinen Namen ein.':field.name==='email'?'Bitte gib deine E-Mail-Adresse ein.':'Bitte beschreibe kurz dein Vorhaben.';else if(field.validity.typeMismatch)message='Bitte gib eine gültige E-Mail-Adresse ein.';else if(field.validity.tooShort||(field.name==='message'&&field.value.trim().length<10))message='Bitte beschreibe dein Vorhaben mit mindestens 10 Zeichen.';let hint=document.getElementById(field.id+'-error');if(!hint){hint=document.createElement('span');hint.id=field.id+'-error';hint.className='field-error';field.after(hint);field.setAttribute('aria-describedby',hint.id)}hint.textContent=message;field.setAttribute('aria-invalid',String(Boolean(message)));return !message}fields.forEach(field=>{field.addEventListener('blur',()=>{if(field.value||field.getAttribute('aria-invalid')==='true')validate(field)});field.addEventListener('input',()=>{if(field.getAttribute('aria-invalid')==='true')validate(field)})});let sending=false;form.addEventListener('submit',async event=>{event.preventDefault();if(sending)return;const valid=fields.map(validate);if(valid.includes(false)){fields[valid.indexOf(false)].focus();return;}if(form.elements._honey.value)return;status.classList.remove('is-error');sending=true;button.disabled=true;button.textContent='Wird gesendet …';status.textContent='Deine Anfrage wird übermittelt.';form.setAttribute('aria-busy','true');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch('https://formsubmit.co/ajax/kontakt@sanscale.de',{method:'POST',body:new FormData(form),headers:{Accept:'application/json'},signal:controller.signal});const result=await response.json();if(!response.ok||!(result.success===true||result.success==='true'))throw new Error(/activation/i.test(result.message||'')?'activation':'submission failed');status.textContent='Danke! Du wirst zur Bestätigung weitergeleitet.';form.reset();window.location.assign('/danke.html')}catch(error){status.classList.add('is-error');const message=error.name==='AbortError'?'Die Rückmeldung dauert länger als erwartet. Deine Anfrage könnte bereits angekommen sein. Bitte sende sie nicht sofort erneut. Kontaktiere uns bei Unsicherheit per E-Mail.':error.message==='activation'?'Der Formularversand ist noch nicht freigeschaltet. Bitte kontaktiere uns per E-Mail.':'Der Versand konnte nicht bestätigt werden. Bitte kontaktiere uns bei Unsicherheit per E-Mail, bevor du die Anfrage erneut sendest.';status.replaceChildren(document.createTextNode(message+' Deine Eingaben bleiben erhalten. '));const email=document.createElement('a');email.href='mailto:kontakt@sanscale.de';email.textContent='kontakt@sanscale.de';status.append(email);status.setAttribute('tabindex','-1');status.focus();}finally{clearTimeout(timer);sending=false;button.disabled=false;button.textContent='Projekt anfragen';form.removeAttribute('aria-busy')}})})();